//! 🧪️ Authored metadata preserves original allocations across bounded hashing and cancellation.
use super::*;
#[test]
fn original_checkpoint_publishes_authored_graph_and_causal_event_atomically(){
 type Metadata=semio_framework_os_store_engine_replay::checkpoint::OriginalCheckpointPublication<Mutation>;
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../⚙️engine/🌿️branch/commit.json")).unwrap();
 for cut in fixture["cuts"].as_array().unwrap().iter().map(|n|Some(n.as_u64().unwrap()as usize)).chain([Some(usize::MAX),None]){
 let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut store=native_document_store(&mut caller,&mut decoder);let g=RetainedCloneGrant{maximum_copy_bytes:32768,maximum_capacity_bytes:16<<20,..TURN};let result=semio_framework_os_store_engine_replay::prepare_report(&mut store,&mut caller,&mut decoder);crate::original_stream_abort::close_report_fixture(result,&mut caller,&mut decoder);
 let message=format!("{}{}",fixture["message"].as_str().unwrap(),fixture["suffix"].as_str().unwrap().repeat(fixture["repeat"].as_u64().unwrap()as usize));let mut donors=None;turn(&mut caller,&mut decoder,RetainedCloneGrant{maximum_copy_bytes:message.len()+512,..g},|cx|{let author=&fixture["author"];let capacity=message.len()+size_of::<store::Author>()+author["id"].as_str().unwrap().len()+author["name"].as_str().unwrap().len();let d=OriginalConstructionDemand{items:1,copy_bytes:message.len()+512,capacity_bytes:capacity,release_bytes:0,depth:1};admit_original_construction(cx,&mut donors,d,|_|Ok(((message.clone(),vec![store::Author{id:author["id"].as_str().unwrap().into(),name:author["name"].as_str().unwrap().into(),avatar:None}]),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:capacity,..Default::default()})))?;Ok(())});let(message,mut authors)=donors.take().unwrap();let mut message=Some(message);let pointer=message.as_ref().unwrap().as_ptr();let authors_pointer=authors.as_ptr();let mut source=None;let birth=Metadata::capture_demands();for axis in [0,1,2,4]{let mut denied=g;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=birth.copy_bytes-1,2=>denied.maximum_capacity_bytes=birth.capacity_bytes-1,_=>denied.maximum_depth=0};turn(&mut caller,&mut decoder,denied,|cx|{assert!(!Metadata::admit(&store,&mut message,&mut authors,cx,&mut source)?);Ok(())});assert_eq!(message.as_ref().unwrap().as_ptr(),pointer);assert_eq!(authors.as_ptr(),authors_pointer);}turn(&mut caller,&mut decoder,g,|cx|{assert!(Metadata::admit(&store,&mut message,&mut authors,cx,&mut source)?);Ok(())});assert!(message.is_none()&&authors.is_empty());let mut foreign=OriginalJobDecodeOwner::empty();turn(&mut caller,&mut foreign,g,|cx|{assert!(source.as_mut().unwrap().advance(&mut store,cx).is_err());Ok(())});
 for index in 0..262144{if cut==Some(index)||source.as_ref().unwrap().prepared(){break}turn(&mut caller,&mut decoder,g,|cx|source.as_mut().unwrap().advance(&mut store,cx));assert!(index<262143);}if cut.is_none(){assert!(source.as_ref().unwrap().prepared());assert!(store.parts_ref().log.envelope.vcs.checkpoints.is_empty());assert!(store.parts_ref().log.envelope.vcs.changes.is_empty());assert!(store.parts_ref().log.envelope.transitions.is_empty());turn(&mut caller,&mut decoder,g,|cx|{assert!(source.as_mut().unwrap().publish(&mut store,cx)?);Ok(())});let parts=store.parts_ref();let checkpoint=parts.log.envelope.vcs.checkpoints.get(0).unwrap();let change=parts.log.envelope.vcs.changes.get(0).unwrap();assert_eq!(checkpoint.message.as_ref().unwrap().as_ptr(),pointer);assert_eq!(checkpoint.authors.as_ptr(),authors_pointer);assert_eq!(change.description,checkpoint.message);assert_eq!(parts.log.current_checkpoint_id.as_deref(),Some(checkpoint.id.as_str()));assert_eq!(parts.log.envelope.cursor.as_ref().unwrap().checkpoint_id,Some(checkpoint.id.clone()));assert_eq!(parts.log.envelope.transitions.len(),1);assert_eq!(parts.wire.original_outbox.len(),1);assert_eq!(store.snapshot().unwrap().zoom,1.25);exercise_checkpoint_order(&store,&mut caller,&mut decoder);}else{caller.cancel().cancel_now();}
 for index in 0..262144{if source.as_ref().unwrap().terminal_is_empty(){break}let d=source.as_ref().unwrap().close_demands(&store,4096).unwrap();let exact=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};for axis in 0..5{let mut denied=exact;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes-=1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes-=1,3 if d.release_bytes>0=>denied.maximum_release_bytes-=1,4 if d.depth>0=>denied.maximum_depth-=1,_=>continue};turn(&mut caller,&mut decoder,denied,|cx|cx.with_original_retirement(|cx|{assert!(!source.as_mut().unwrap().close_step(&mut store,4096,cx)?);Ok(())}));assert_eq!(source.as_ref().unwrap().close_demands(&store,4096).unwrap(),d);}turn(&mut caller,&mut decoder,exact,|cx|cx.with_original_retirement(|cx|source.as_mut().unwrap().close_step(&mut store,4096,cx)));assert!(index<262143);}
 turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=RetirementDemand{copy_bytes:size_of::<Option<Box<Metadata>>>(),release_bytes:size_of::<Metadata>(),depth:1,..Default::default()};close_original_retained_step(cx,d,|_|{source=None;Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())}));for index in 0..1048576{if store.close_owned_store_terminal_is_empty(){break}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=store.close_owned_demands(4096)?;close_original_retained_step(cx,d,|grant|store.close_owned_store_step(grant))?;Ok(())}));assert!(index<1048575);}release_native_store_box(store,&mut caller,&mut decoder);while !decoder.terminal_is_empty(){caller.turn(g,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|grant|decoder.close_step(grant))?;Ok(())})).unwrap();}caller.retire(g);
 }
}

fn exercise_checkpoint_order(store:&store::ArtifactStore<State,Mutation>,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){
 type Order=store::os_store::OriginalCheckpointEditOrder;
 let id=store.parts_ref().log.envelope.vcs.checkpoints.get(0).unwrap().id.clone();let g=RetainedCloneGrant{maximum_copy_bytes:32768,maximum_capacity_bytes:16<<20,..TURN};
 for cut in [Some(0),Some(1),Some(8),Some(32),None]{let mut source=None;let d=Order::capture_demands();for axis in [0,1,2,4]{let mut denied=g;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=d.copy_bytes-1,2=>denied.maximum_capacity_bytes=d.capacity_bytes-1,_=>denied.maximum_depth=d.depth-1};turn(caller,decoder,denied,|cx|{assert!(!Order::admit(store,&id,cx,&mut source)?);Ok(())});assert!(source.is_none());}turn(caller,decoder,g,|cx|{assert!(Order::admit(store,&id,cx,&mut source)?);Ok(())});let foreign=id.clone();turn(caller,decoder,g,|cx|{assert!(source.as_mut().unwrap().advance(store,&foreign,cx).is_err());Ok(())});let mut ready=false;for index in 0..262144{if cut==Some(index){break}let d=source.as_ref().unwrap().advance_demands().unwrap();let exact=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};for axis in [0,1,2,4]{let mut denied=exact;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes-=1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes-=1,4 if d.depth>0=>denied.maximum_depth-=1,_=>continue};turn(caller,decoder,denied,|cx|{assert!(!source.as_mut().unwrap().advance(store,&id,cx)?);Ok(())});assert_eq!(source.as_ref().unwrap().advance_demands().unwrap(),d);}ready=turn(caller,decoder,exact,|cx|source.as_mut().unwrap().advance(store,&id,cx));if ready{break}assert!(index<262143);}if cut.is_none(){assert!(ready);let order=source.as_ref().unwrap().borrow_order().unwrap();assert_eq!(order.len(),1);let edit=store.parts_ref().log.envelope.vcs.edits.get_key(*order.get(0).unwrap()).unwrap();assert_eq!(edit.id,store.parts_ref().log.envelope.vcs.changes.get(0).unwrap().edit_ids[0]);}
 for index in 0..262144{if source.as_ref().unwrap().terminal_is_empty(){break}let d=source.as_ref().unwrap().close_demands(4096).unwrap();let exact=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};for axis in 0..5{let mut denied=exact;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes-=1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes-=1,3 if d.release_bytes>0=>denied.maximum_release_bytes-=1,4 if d.depth>0=>denied.maximum_depth-=1,_=>continue};turn(caller,decoder,denied,|cx|cx.with_original_retirement(|cx|{assert!(!source.as_mut().unwrap().close_step(store,cx)?);Ok(())}));assert_eq!(source.as_ref().unwrap().close_demands(4096).unwrap(),d);}turn(caller,decoder,exact,|cx|cx.with_original_retirement(|cx|source.as_mut().unwrap().close_step(store,cx)));assert!(index<262143);}turn(caller,decoder,g,|cx|cx.with_original_retirement(|cx|{let d=Order::boxed_release_demands();close_original_retained_step(cx,d,|_|{source=None;Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())}));}
}
